# Pudding Sword Cursor -- uninstall
# Generated by cursor-studio cursorgen -- edit the theme, not this file.
#
# Everything stays inside your user profile:
#   files    : %LOCALAPPDATA%\Cursors\Pudding Sword Cursor
#   registry : HKCU\Control Panel\Cursors (+ the Schemes sub-key)
# Administrator rights are NOT required.
#
# Use -DryRun to see what would happen without changing anything.

param([switch]$DryRun)

$ErrorActionPreference = 'Stop'

$ThemeName   = 'Pudding Sword Cursor'
$SourceDir   = $PSScriptRoot
$CursorsKey  = 'HKCU:\Control Panel\Cursors'
$SchemesKey  = 'HKCU:\Control Panel\Cursors\Schemes'
$BackupPath  = Join-Path $SourceDir 'uninstall-backup.json'
$TargetDir   = Join-Path $env:LOCALAPPDATA ('Cursors\' + $ThemeName)

# slot order == the order Windows expects in the scheme string
$Slots = [ordered]@{
    'Arrow'        = '01 Arrow.ani'
    'Help'         = '02 Help.ani'
    'AppStarting'  = '03 AppStarting.ani'
    'Wait'         = '04 Wait.ani'
    'Crosshair'    = '05 Crosshair.ani'
    'IBeam'        = '06 IBeam.ani'
    'NWPen'        = '07 NWPen.ani'
    'No'           = '08 No.ani'
    'SizeNS'       = '09 SizeNS.ani'
    'SizeWE'       = '10 SizeWE.ani'
    'SizeNWSE'     = '11 SizeNWSE.ani'
    'SizeNESW'     = '12 SizeNESW.ani'
    'SizeAll'      = '13 SizeAll.ani'
    'UpArrow'      = '14 UpArrow.ani'
    'Hand'         = '15 Hand.ani'
}

$AeroFallback = [ordered]@{
    'Arrow'          = @('aero_arrow.cur', 'arrow_m.cur')
    'Help'           = @('aero_helpsel.cur', 'help_m.cur')
    'AppStarting'    = @('aero_working.ani', 'appstarting.ani')
    'Wait'           = @('aero_busy.ani', 'wait_m.cur')
    'Crosshair'      = @('aero_cross.cur', 'cross_m.cur')
    'IBeam'          = @('aero_ibeam.cur', 'beam_m.cur')
    'NWPen'          = @('aero_pen.cur', 'pen_m.cur')
    'No'             = @('aero_unavail.cur', 'no_m.cur')
    'SizeNS'         = @('aero_ns.cur', 'size3_m.cur')
    'SizeWE'         = @('aero_ew.cur', 'size2_m.cur')
    'SizeNWSE'       = @('aero_nwse.cur', 'size4_m.cur')
    'SizeNESW'       = @('aero_nesw.cur', 'size1_m.cur')
    'SizeAll'        = @('aero_move.cur', 'move_m.cur')
    'UpArrow'        = @('aero_up.cur', 'up_m.cur')
    'Hand'           = @('aero_link.cur', 'link_m.cur')
}

function Update-Cursors {
    if ($DryRun) {
        Write-Host '  [dry-run] would call SystemParametersInfo(SPI_SETCURSORS)'
        return
    }
    # SPI_SETCURSORS = 0x0057, SPIF_UPDATEINIFILE | SPIF_SENDCHANGE = 0x0003
    if (-not ('CursorTheme.Native' -as [type])) {
        Add-Type -Namespace CursorTheme -Name Native -MemberDefinition @'
[DllImport("user32.dll", SetLastError = true)]
public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, System.IntPtr pvParam, uint fWinIni);
'@
    }
    [void][CursorTheme.Native]::SystemParametersInfo(0x0057, 0, [IntPtr]::Zero, 0x0003)
}

function Set-CursorValue([string]$Name, [string]$Value) {
    if ([string]::IsNullOrWhiteSpace($Value)) {
        if ($DryRun) {
            Write-Host ("  [dry-run] remove HKCU\\Control Panel\\Cursors\\" + $Name)
        } else {
            Remove-ItemProperty -Path $CursorsKey -Name $Name -ErrorAction SilentlyContinue
        }
        return
    }
    if ($DryRun) {
        Write-Host ("  [dry-run] HKCU\\Control Panel\\Cursors\\" + $Name + " = " + $Value)
        return
    }
    Set-ItemProperty -Path $CursorsKey -Name $Name -Value $Value -Type String
}

function Restore-WindowsDefaults {
    # 1) if a Windows scheme is registered, reuse its exact 15-entry string
    foreach ($name in @('Windows Aero', 'Windows Default', 'Windows 默认')) {
        try {
            $entry = Get-ItemProperty -Path $SchemesKey -Name $name -ErrorAction Stop
        } catch {
            continue
        }
        $parts = [string]$entry.$name -split ','
        if ($parts.Count -eq 15) {
            $index = 0
            foreach ($role in $Slots.Keys) {
                Set-CursorValue $role $parts[$index].Trim()
                $index++
            }
            return ("the Windows scheme '" + $name + "'")
        }
    }
    # 2) otherwise point at Windows' own aero/classic cursor files
    $windowsDir = Join-Path $env:SystemRoot 'Cursors'
    foreach ($role in $Slots.Keys) {
        $chosen = $null
        foreach ($candidate in $AeroFallback[$role]) {
            $path = Join-Path $windowsDir $candidate
            if (Test-Path -LiteralPath $path) { $chosen = $path; break }
        }
        if ($chosen) { Set-CursorValue $role $chosen }
        else { Set-CursorValue $role '' }
    }
    return 'the Windows default cursors'
}

Write-Host ''
Write-Host ("Removing '" + $ThemeName + "' ...") -ForegroundColor Cyan
if ($DryRun) { Write-Host '  (dry run: nothing will be changed)' }

$restored = ''
if (Test-Path -LiteralPath $BackupPath) {
    $backup = Get-Content -LiteralPath $BackupPath -Raw | ConvertFrom-Json
    $names = @()
    if ($backup.values) { $names = @($backup.values.PSObject.Properties.Name) }
    foreach ($role in $Slots.Keys) {
        if ($names -contains $role) {
            Set-CursorValue $role ([string]$backup.values.$role)
        } else {
            Set-CursorValue $role ''
        }
    }
    if ($names -contains 'Scheme') { Set-CursorValue 'Scheme' ([string]$backup.values.Scheme) }
    if ($DryRun) {
        Write-Host '  [dry-run] would delete uninstall-backup.json'
    } else {
        Remove-Item -LiteralPath $BackupPath -Force
    }
    $restored = 'the settings saved in uninstall-backup.json'
    Write-Host '  restoring the previous cursor settings'
} else {
    $restored = Restore-WindowsDefaults
    Set-CursorValue 'Scheme' ''
    Write-Host ("  no backup found, restoring " + $restored)
}

# remove the scheme entry and the copied files
if ($DryRun) {
    Write-Host ("  [dry-run] remove the scheme entry '" + $ThemeName + "'")
    Write-Host ("  [dry-run] delete " + $TargetDir)
} else {
    Remove-ItemProperty -Path $SchemesKey -Name $ThemeName -ErrorAction SilentlyContinue
    if (Test-Path -LiteralPath $TargetDir) {
        Remove-Item -LiteralPath $TargetDir -Recurse -Force
        Write-Host ("  deleted " + $TargetDir)
    }
}

Update-Cursors

Write-Host ''
if ($DryRun) {
    Write-Host 'Dry run finished: nothing was changed.' -ForegroundColor Yellow
} else {
    Write-Host ("Done. Restored " + $restored + ".") -ForegroundColor Green
    Write-Host 'The theme folder itself was left alone -- delete it whenever you like.'
}
